script:
// Lejtő súrlódással – az erők felbontása
// Inclined plane with friction – resolving the forces
//   a = g·(sin α − μ·cos α), ha tg α > μ  /  if tan α > μ

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#f8f9fb");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Lejtő", en: "Inclined plane"});
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(4);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("alpha", {hu: "Hajlásszög α", en: "Angle α"}, 0, 60, 30, 1, "°");
param("mu",    {hu: "Súrlódási együttható μ", en: "Friction coefficient μ"}, 0, 1, 0.25, 0.01, "");
param("m",     {hu: "Tömeg m", en: "Mass m"}, 0.5, 20, 2, 0.5, "kg");
param("g",     {hu: "Nehézségi gyorsulás g", en: "Gravity g"}, 1, 25, 9.81, 0.01, "m/s²");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("comp", {hu: "mg összetevői", en: "Components of mg"}, true);
// Ezek változásakor a jelenet újraindul / The scene restarts when these change
resetOn("alpha");
// Gomb a Vezérlők fülön / Button on the Controls tab
button({hu: "Újraindítás", en: "Restart"}, reset);

const L = 8;          // a lejtő hossza / length of the slope [m]
let s = 0.4, v = 0, a = 0;

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => {
  const al = deg(P.alpha);
  // Erők: lejtő irányú, nyomóerő, súrlódás / forces: along the slope, normal, friction
  const Fp = P.m * P.g * sin(al), Fn = P.m * P.g * cos(al), Fs = P.mu * Fn;
  // Mozog, ha már csúszik, vagy ha tg α > μ / it moves if already sliding or if tan α > μ
  if (v > 1e-9 || Fp > Fs) a = (Fp - Fs) / P.m; else a = 0;
  v += a * dt;
  if (v < 0) { v = 0; a = 0; }
  s += v * dt;
  if (s > L - 0.4) { s = L - 0.4; v = 0; a = 0; }
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  const al = deg(P.alpha);
  // A lejtő mérete úgy, hogy elférjen a vásznon / slope size so that it fits on the canvas
  const Lpx = min(760 / max(cos(al), 0.01), 400 / max(sin(al), 0.01));
  const Bx = 120, By = 500;                                  // alsó csúcs / bottom vertex
  const Tx = Bx + Lpx * cos(al), Ty = By - Lpx * sin(al);    // felső csúcs / top vertex
  ground(By, {x1: 40, x2: 960});
  polygon([[Bx, By], [Tx, Ty], [Tx, By]], {fill: "#e6eaf0", stroke: C.gray, lw: 2});
  arc(Bx, By, 64, -al, 0, {stroke: C.ink, lw: 1.5});
  text("α", Bx + 84 * cos(al / 2), By - 84 * sin(al / 2) + 6, {size: 18, italic: true, align: "center"});

  // A test helyzete / block position (s a csúcstól / s measured from the top)
  const ux = -cos(al), uy = sin(al);          // lejtőn lefelé / down the slope
  const nx = -sin(al), ny = -cos(al);         // a felületre merőleges / surface normal
  const px = Tx + ux * (s / L) * Lpx, py = Ty + uy * (s / L) * Lpx;
  const bw = 70, bh = 44;
  const cxb = px + nx * bh / 2, cyb = py + ny * bh / 2;
  box(cxb, cyb, bw, bh, -al, {fill: C.blue, stroke: "#173b8f", lw: 1.5});
  text(fmt(P.m, 1) + " kg", cxb, cyb + 5, {size: 13, color: "#fff", align: "center", bold: true});

  // Erők (mg mindig 110 px) / forces (mg is always drawn 110 px long)
  const Fg = P.m * P.g, Fp = Fg * sin(al), Fn = Fg * cos(al);
  const Ff = v > 1e-9 ? P.mu * Fn : min(Fp, P.mu * Fn);
  const k = 110 / Fg;
  vector(cxb, cyb, 0, Fg * k, {stroke: C.red, lw: 3}, "mg");
  vector(cxb, cyb, nx * Fn * k, ny * Fn * k, {stroke: C.blue, lw: 3}, "N");
  if (Ff > 1e-6) vector(cxb, cyb, -ux * Ff * k, -uy * Ff * k, {stroke: C.orange, lw: 3}, "Fs");
  if (P.comp) {
    vector(cxb, cyb, ux * Fp * k, uy * Fp * k, {stroke: C.red, lw: 1.8, dash: [5, 4]}, "mg·sin α");
    vector(cxb, cyb, -nx * Fn * k, -ny * Fn * k, {stroke: C.red, lw: 1.8, dash: [5, 4]}, "mg·cos α");
  }

  const slides = tan(al) > P.mu;
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Gyorsulás a", en: "Acceleration a"}, a, "m/s²");
  show({hu: "Sebesség v", en: "Speed v"}, v, "m/s");
  show({hu: "Megtett út s", en: "Distance s"}, s - 0.4, "m");
  show({hu: "Lejtő irányú erő mg·sin α", en: "Along-slope force mg·sin α"}, Fp, "N");
  show({hu: "Nyomóerő N = mg·cos α", en: "Normal force N = mg·cos α"}, Fn, "N");
  show({hu: "Súrlódási erő", en: "Friction force"}, Ff, "N");
  show({hu: "tg α", en: "tan α"}, tan(al), "");
  show({hu: "Állapot", en: "State"}, tr(v > 1e-9 ? {hu: "csúszik", en: "sliding"} : slides ? {hu: "indul", en: "starting"} : {hu: "nyugalomban (tg α ≤ μ)", en: "at rest (tan α ≤ μ)"}), "");

  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Sebesség v", en: "Speed v"}, v, {unit: "m/s", color: C.blue});
  plot({hu: "Megtett út s", en: "Distance s"}, s - 0.4, {unit: "m", color: C.green});
});
